export async function signIn(f){const boot=await f.post('academy','/auth/v2/bootstrap',{purpose:'pin',loginId:f.loginId,expectedContext:null});assert.equal(boot.response.status,200,JSON.stringify(boot.data));const login=await f.post('academy','/auth/v2/pin',{loginId:f.loginId,pin:'1234',tx:boot.data.tx,attemptId:boot.data.attemptId,operationId:boot.data.intent.id,expectedContext:null},boot.data);assert.equal(login.response.status,200,JSON.stringify(login.data));return login.data;}
export async function world({prepareAcademy,prepareSource,prepareEnvironment,studioAuthority,hook}={}){const f=await createNativeHTTPFixture({prepareAcademy,prepareSource,prepareEnvironment,studioAuthority}),env=f.envs.academy;f.databases.academy.exec("UPDATE split_deployment_state SET state='READY'");env.ACADEMY_D1_RUN_ID=f.databases.academy.prepare('SELECT source_digest FROM split_deployment_state WHERE singleton=1').get().source_digest;env.UAA_V2_ENABLED='1';env.UAA_V2_CONFIG=JSON.stringify(f.runtimes.academy.settings.raw);env.UAA_V2_COORDINATOR_KEY=opaque();
 const engine=splitEngine({v2Env:env,hook,clock:f.now,core:emptyCompatibilityDatabase(env.ACADEMY_DB,emptyShapes,{currentGrants:true}),admin:env.ACADEMY_ADMIN_DB});env.ACADEMY_SPLIT_COORDINATOR={getByName:()=>({async read(...args){return {result:await engine.read(...args)};},async write(...args){return {result:await engine.write(...args)};}})};
 const background=new Set(),backgroundErrors=[];const context={waitUntil(promise){const task=Promise.resolve(promise).catch(error=>{backgroundErrors.push(error);}).finally(()=>background.delete(task));background.add(task);}};const drainNativeBackground=async()=>{while(background.size)await Promise.all([...background]);};let nativeError=null;const native=createAcademyWorker(undefined,{onError:e=>{nativeError=e;}}),handle=createAcademyV2Handler({getRuntime:async()=>f.runtimes.academy,business:(request,bindings,ctx)=>native.fetch(request,bindings,ctx),service:async(request,bindings,ctx,runtime)=>{const path=new URL(request.url).pathname;if(path==='/internal/website/portal-return/v2')return (await import('../../src/academy/v111/portal-return.mjs')).receivePortalReturn(request,runtime,{env:bindings,requestNative:(r,e)=>native.fetch(r,e,ctx)});return Response.json({code:'FIXTURE_SERVICE_NOT_REGISTERED'},{status:404});}});f.setAcademyHandler(r=>handle(r,env,context));
 async function request(path,input,login,{method='POST',headers={}}={}){const h={Origin:'https://ummabbadacademy.app','Content-Type':'application/json','X-UAA-Request':'2','Sec-Fetch-Site':'same-origin',Cookie:f.jar.header('https://ummabbadacademy.app'),...headers};if(login){h['X-UAA-CSRF']=login.csrfByPurpose.business;h['X-UAA-Business-Intent']=login.businessIntent.id;h['X-UAA-Expected-Context']=b64u(bytes(canonical(login.context)));}const response=await handle(new Request('https://ummabbadacademy.app'+path,{method,headers:h,body:method==='GET'?undefined:JSON.stringify(input)}),env,context);return {response,data:await response.json(),nativeError};}
 return {...f,nativeRequest:request,nativeHandle:r=>handle(r,env,context),drainNativeBackground,nativeBackgroundErrors:backgroundErrors,lastNativeError:()=>nativeError};}

// Local fixture compatibility only: the common native fixture may already
// have applied these immutable production recipes. Preserve recipes themselves;
// skip only an ADD COLUMN whose exact named column is already present.
function fixtureUpgrade(raw,name){
 let sql=readFileSync(new URL('../../migrations/academy-core/'+name,import.meta.url),'utf8').replace(/CREATE (TABLE|INDEX|UNIQUE INDEX|TRIGGER|VIEW) (?!IF NOT EXISTS)/g,'CREATE $1 IF NOT EXISTS ').replace(/INSERT INTO website_platform_control /g,'INSERT OR IGNORE INTO website_platform_control ');
 sql=sql.replace(/ALTER TABLE ([a-z_]+) ADD COLUMN ([a-z_]+) [^;]*;/gi,(statement,table,column)=>raw.prepare('PRAGMA table_info("'+table+'")').all().some(row=>row.name===column)?'':statement);
 raw.exec(sql);
}
export function prepareAcademyV111Business(raw){for(const name of ['0006_program_monthly_subscriptions.sql','0007_program_surah_websites.sql','0008_program_surah_grants.sql','0011_website_platform.sql','0012_website_schedule_library.sql','0013_website_parallel_access.sql','0014_website_navigation.sql','0015_studio_access_admin.sql'])fixtureUpgrade(raw,name);}

export function prepareAcademyV111SourceAuthority(raw){prepareAcademyV111Business(raw);for(const name of ['0016_course_studio_publication.sql','0017_monthly_programme_bridge.sql','0018_completed_course_studio.sql','0019_course_policy_mirror.sql'])fixtureUpgrade(raw,name);}

export function seedStudioAuthoringFixture(f){const source=f.databases.academy,target=f.databases.studio,row=source.prepare("SELECT a.account_id,a.login_link_id,c.credential_epoch ce FROM accounts a JOIN account_credentials c USING(account_id) JOIN global_role_assignments g USING(account_id) WHERE a.active=1 AND c.pin_setup=1 AND g.role='GLOBAL_ADMIN' AND g.active=1 AND g.review_state='CONFIRMED' ORDER BY a.account_id LIMIT 1").get();assert(row,'actual native Global Admin prerequisite');const activityKey='COURSE:SEPARATION-A',offeringId='native-course',websiteId='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';source.prepare("INSERT INTO website_platform_timetable_scopes(activity_key,offering_id,kind) VALUES(?,?,'COURSE') ON CONFLICT(activity_key) DO UPDATE SET offering_id=excluded.offering_id").run(activityKey,offeringId);source.prepare("INSERT INTO website_platform_access_scopes(activity_key,enabled,purchase_model) VALUES(?,1,'CONFIRMED_SUBSCRIPTION') ON CONFLICT(activity_key) DO UPDATE SET enabled=1,purchase_model='CONFIRMED_SUBSCRIPTION'").run(activityKey);source.prepare("UPDATE course_settings SET legacy_access_model='PAID',policy_review_state='CONFIRMED' WHERE activity_key=?").run(activityKey);target.prepare('INSERT INTO accounts VALUES(?,?,1,1,?,0,0) ON CONFLICT(account_id) DO NOTHING').run(row.account_id,'Synthetic reviewed native Global Admin',row.ce);target.prepare("INSERT INTO websites(website_id,offering_id,title,revision) VALUES(?,?,?,1) ON CONFLICT(website_id) DO NOTHING").run(websiteId,offeringId,'Synthetic unpublished native builder');f.loginId=row.login_link_id;return {sub:row.account_id,ce:row.ce,loginId:row.login_link_id,activityKey,offeringId,websiteId};}
